mapper.sql:
from (
    select 'REVENUE' as kind, r.id as id, r.received_on as occurredOn, r.title as title, r.source as category,
           r.reference as reference, r.amount as amount, r.currency as currency
    from nad_revenue r
    union all
    select 'EXPENSE' as kind, e.id as id, e.spent_on as occurredOn, e.title as title,
           coalesce(c.name, 'Uncategorised') as category, e.receipt_no as reference, e.amount as amount,
           e.currency as currency
    from nad_expense e left join nad_expense_category c on c.id = e.category_id
    where e.status in ('APPROVED', 'PAID')
) l

     and l.kind = #{kind} 
     and l.currency = #{currency} 
     and (l.title like concat('%', #{q}, '%') or l.reference like concat('%', #{q}, '%') or l.category like concat('%', #{q}, '%')) 
     and l.occurredOn >= #{from} 
     and l.occurredOn <= #{to}
